/*
 * prog55_connected_components.c
 *
 * Re‑implementation of the original program that computes the connected
 * components of an undirected graph with at most 8 vertices.
 *
 * The program is invoked as
 *
 *     prog55_connected_components  N  M  u1 v1  u2 v2  ...  uM vM
 *
 * where
 *   N – number of vertices (0 < N ≤ 8)
 *   M – number of edges   (M ≥ 0)
 *   ui vi – the two endpoints of the i‑th edge (0 ≤ ui,vi < N)
 *
 * If the input is malformed the program prints the single line
 *
 *     INVALID_INPUT
 *
 * and returns exit status 1.  Otherwise it prints each connected component
 * on its own line in the form
 *
 *     k: {v0,v1,...,vk}
 *
 * where `k` is the component number starting from 0 and the vertices are
 * listed in the order they are discovered by a breadth‑first search.
 *
 * The original binary was heavily obfuscated; the logic above reproduces
 * the observable behaviour (output) of the original program.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAXV 8                     /* maximum number of vertices */

int main(int argc, char *argv[])
{
    /* ---------- input validation ---------- */
    if (argc < 3) {                     /* need at least N and M */
        puts("INVALID_INPUT");
        return 1;
    }

    /* the number of arguments after the program name must be even:
       N, M and then 2*M vertex numbers */
    if ( (argc - 3) % 2 != 0 ) {
        puts("INVALID_INPUT");
        return 1;
    }

    long n = strtol(argv[1], NULL, 10);
    long m = strtol(argv[2], NULL, 10);

    if (n < 1 || n > MAXV) {            /* vertices must be 1..8 */
        puts("INVALID_INPUT");
        return 1;
    }
    if (m < 0) {
        puts("INVALID_INPUT");
        return 1;
    }
    if ( (argc - 3) != 2 * m ) {        /* exactly M edge pairs must be present */
        puts("INVALID_INPUT");
        return 1;
    }

    /* ---------- build adjacency matrix ---------- */
    bool adj[MAXV][MAXV] = { { false } };
    for (long i = 0; i < m; ++i) {
        long u = strtol(argv[3 + 2*i],     NULL, 10);
        long v = strtol(argv[3 + 2*i + 1], NULL, 10);

        if (u < 0 || u >= n || v < 0 || v >= n) {
            puts("INVALID_INPUT");
            return 1;
        }

        adj[u][v] = true;
        adj[v][u] = true;                /* undirected graph */
    }

    /* ---------- BFS to find connected components ---------- */
    bool visited[MAXV] = { false };
    int  queue[MAXV];
    int  comp_id = 0;                    /* component counter */

    for (int start = 0; start < n; ++start) {
        if (visited[start])
            continue;                    /* already part of a previous component */

        /* print component header */
        printf("%d: {", comp_id);

        /* BFS initialisation */
        int qhead = 0, qtail = 0;
        queue[qtail++] = start;
        visited[start] = true;
        bool first_vertex = true;

        while (qhead < qtail) {
            int u = queue[qhead++];
            if (!first_vertex)
                putchar(',');            /* separator between vertices */
            printf("%d", u);
            first_vertex = false;

            /* enqueue all unvisited neighbours of u */
            for (int v = 0; v < n; ++v) {
                if (adj[u][v] && !visited[v]) {
                    visited[v] = true;
                    queue[qtail++] = v;
                }
            }
        }

        putchar('}');
        putchar('\n');
        ++comp_id;
    }

    return 0;
}
